'use strict';
const M=GDSkills,C=GDConcepts,$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const records=SKILLS_DATA.records,byId=new Map(records.map(r=>[r.id,r])),storageKey='gd-skills-pilot-v1';
const outcomes={assisted:'Performance with AI',unaided:'Immediate unaided performance',retention:'Later unaided retention',agency:'Agency / control',other:'Other outcome',unknown:'Unknown'};
const durations={immediate:'Same session',days:'Days',weeks:'Weeks',months:'Months or longer',unknown:'Unknown'};
const initialQueue=records.filter(r=>r.kind==='study'&&!M.isRetracted(r)&&(r.landscape||[]).some(c=>['human','both'].includes(c.side))&&C.match(r,C.defaults).length).sort((a,b)=>C.match(b,C.defaults).length-C.match(a,C.defaults).length||a.id.localeCompare(b.id)).slice(0,40).map(r=>r.id);
let rules=C.validateRules(C.defaults),reviews={},drafts={},queue=[...initialQueue],gapNote='',cache=new Map(),state=M.readQuery(location.search),page=1,showAllPairs=false,allPairs=[],visibleRows=[],matrixRows=[],storageBlocked=false;
const options=(map,value)=>Object.entries(map).map(([id,label])=>`<option value="${esc(id)}"${id===value?' selected':''}>${esc(label)}</option>`).join('');
const status=r=>reviews[r.id]?.status==='checked'?'Source checked by you':reviews[r.id]?.status==='excluded'?'Excluded by you':'Unreviewed';
const cite=r=>M.citation(r,SKILLS_DATA.citations),citeLabel=r=>cite(r)===null?'Citation count unknown':cite(r).toLocaleString()+' citations';
const label=id=>rules.find(c=>c.id===id)?.label||M.areas.find(a=>a.id===id)?.label||id;
const safeURL=url=>{try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch(_){return '#';}};
function matches(r){if(!cache.has(r.id))cache.set(r.id,C.match(r,rules));return cache.get(r.id);}
function context(){return {matches,reviews,queue,citations:SKILLS_DATA.citations};}
function workspace(){return {schemaVersion:1,scope:'skills',libraryUpdated:SKILLS_DATA.updated,rules,reviews,drafts,queue,gapNote};}
function validateWorkspace(w){
 if(!w||w.schemaVersion!==1)throw Error('Unsupported workspace version.');
 const nextRules=C.validateRules(w.rules);if(!Array.isArray(w.queue)||w.queue.length>records.length||new Set(w.queue).size!==w.queue.length||w.queue.some(id=>!byId.has(id)))throw Error('This queue includes references outside the current Skills collection. Use the original pilot to open a whole-catalog workspace.');
 function checkedMap(input,isDraft=false){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Invalid review records.');const result={};for(const [id,r]of Object.entries(input)){if(!byId.has(id))throw Error('A reference is missing from this collection; no changes were made.');const v=C.validateReview(isDraft?{...r,status:'unreviewed'}:r);if(isDraft){if(!['unreviewed','checked','excluded'].includes(r.status))throw Error('Invalid draft status.');v.status=r.status;}result[id]=v;}return result;}
 if(typeof w.gapNote!=='string'||w.gapNote.length>20000)throw Error('Invalid research note.');
 return {rules:nextRules,reviews:checkedMap(w.reviews),drafts:checkedMap(w.drafts||{},true),queue:[...w.queue],gapNote:w.gapNote};
}
function applyWorkspace(w){rules=w.rules;reviews=w.reviews;drafts=w.drafts;queue=w.queue;gapNote=w.gapNote;cache.clear();}
function persist(){if(storageBlocked)return;try{localStorage.setItem(storageKey,JSON.stringify(workspace()));$('storage-note').textContent='Edits and drafts saved in this browser. Export to preserve or share your workspace.';}catch(_){$('storage-note').textContent='Browser storage is unavailable. Export before leaving to preserve your work.';}}
try{const saved=localStorage.getItem(storageKey);if(saved)applyWorkspace(validateWorkspace(JSON.parse(saved)));}catch(e){storageBlocked=true;$('message').textContent='The saved workspace could not be loaded: '+e.message;$('storage-note').textContent='Existing saved data has been preserved. Export any new work before leaving.';}
function writeURL(){const q=M.query(state);history.replaceState(null,'',location.pathname+(q?'?'+q:''));}
function syncControls(){for(const k of Object.keys(M.defaults)){const input=$(k);if(input)input.value=state[k];}document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===state.view)));}
function change(patch){state={...state,...patch};if(state.connection===state.concept)state.connection='';page=1;writeURL();syncControls();render();}
function renderRules(){
 $('rules-list').innerHTML=rules.map(c=>`<div class="rule-card"><h3>${esc(c.label)}</h3><p>${esc(c.definition)}</p><label>Matching phrases for ${esc(c.label)}<textarea data-rule="${c.id}" maxlength="8000">${esc(c.terms.join('\n'))}</textarea></label><p id="rule-count-${c.id}"></p></div>`).join('');
 const opts=Object.fromEntries(rules.map(c=>[c.id,c.label]));$('concept').innerHTML=options({'':'All concepts',...opts},state.concept);$('connection').innerHTML=options({'':'Any connection',...opts},state.connection);
 $('area').innerHTML=options({'':'All GD areas',...Object.fromEntries(M.areas.map(a=>[a.id,a.label]))},state.area);$('area2').innerHTML=options({'':'Any GD area',...Object.fromEntries(M.areas.map(a=>[a.id,a.label]))},state.area2);
}
function choosePaper(id,focus=true){if(!byId.has(id))return;state.paper=id;writeURL();renderInspector();drawGraph();if(focus){$('inspector').focus({preventScroll:true});if(window.matchMedia('(max-width:760px)').matches)$('inspector').scrollIntoView({behavior:'auto',block:'start'});}}
function choosePair(a,b){if(state.view==='areas'){change({area:a,area2:b,concept:'',connection:''});}else change({concept:a,connection:b,area:'',area2:''});}
function drawGraph(){
 const nodes=state.view==='concepts'?rules:M.areas,idsFor=r=>state.view==='concepts'?matches(r).map(m=>m.id):r.topics.filter(id=>M.areas.some(a=>a.id===id));
 const base=M.select(records,{...state,concept:'',connection:'',area:'',area2:''},context());allPairs=M.pairs(base,idsFor);
 const points={};nodes.forEach((n,i)=>{const a=-Math.PI/2+i*2*Math.PI/nodes.length;points[n.id]=[440+Math.cos(a)*300,285+Math.sin(a)*230];});
 const active=id=>state.view==='concepts'?[state.concept,state.connection].includes(id):[state.area,state.area2].includes(id);
 let svg='<title>References connected by shared concepts or GD topic assignments</title>';
 svg+=allPairs.map(p=>{const a=points[p.a],b=points[p.b],d=`M${a[0]} ${a[1]} Q440 285 ${b[0]} ${b[1]}`,selected=active(p.a)&&active(p.b)||state.view==='areas'&&[p.a,p.b].includes(state.area);return `<g class="graph-edge" data-pair-a="${p.a}" data-pair-b="${p.b}" role="button" tabindex="0" aria-label="${esc(label(p.a))} and ${esc(label(p.b))}: ${p.ids.length} shared references"><path class="visible-edge" d="${d}" style="stroke-width:${Math.min(5,1+Math.sqrt(p.ids.length)*.35)};${selected?'opacity:.6':''}"/><path class="edge-hit" d="${d}"/><title>${esc(label(p.a))} ↔ ${esc(label(p.b))}: ${p.ids.length} shared references</title></g>`;}).join('');
 const shown=visibleRows.filter(r=>idsFor(r).length).slice(0,24);
 let dots='';shown.forEach((r,i)=>{const a=i*2.39996,x=440+Math.cos(a)*(35+Math.sqrt(i)*23),y=285+Math.sin(a)*(30+Math.sqrt(i)*18),radius=M.radius(cite(r),state.size);for(const id of idsFor(r)){const pt=points[id];svg+=`<line class="paper-link" x1="${x}" y1="${y}" x2="${pt[0]}" y2="${pt[1]}"/>`;}dots+=`<g data-paper="${esc(r.id)}" class="graph-paper ${cite(r)===null?'unknown':''} ${state.paper===r.id?'selected':''}" role="button" tabindex="0" aria-label="Open ${esc(r.title)}; ${citeLabel(r)}"><circle class="paper-hit" cx="${x}" cy="${y}" r="${Math.max(14,radius+5)}" fill="transparent"/><circle class="paper-fill" cx="${x}" cy="${y}" r="${radius}"/><title>${esc(r.title)} · ${citeLabel(r)}</title></g>`;});
 svg+=nodes.map(n=>{const [x,y]=points[n.id],count=base.filter(r=>idsFor(r).includes(n.id)).length;const words=n.label.split(' '),cut=words.length>2?Math.ceil(words.length/2):0,lines=cut?[words.slice(0,cut).join(' '),words.slice(cut).join(' ')]:[n.label];return `<g class="graph-node ${active(n.id)?'active':''} ${count?'':'empty'}" data-node="${n.id}" role="button" tabindex="0" aria-pressed="${active(n.id)}" aria-label="Filter by ${esc(n.label)}: ${count} references"><circle class="node-ring" cx="${x}" cy="${y}" r="18"/><circle class="node-core" cx="${x}" cy="${y}" r="6"/>${lines.map((l,j)=>`<text class="graph-label" x="${x}" y="${y+34+j*17}" text-anchor="middle">${esc(l)}</text>`).join('')}<text class="graph-count" x="${x}" y="${y-29}" text-anchor="middle">${count}</text><title>${esc(n.definition||n.label)}</title></g>`;}).join('')+dots;
 $('graph').innerHTML=svg;$('result-count').textContent=`${visibleRows.length} reference${visibleRows.length===1?'':'s'} · ${shown.length} on map`;
 $('map-hint').textContent=`${state.view==='concepts'?'Select a concept or a line to find shared papers.':'Topic assignments in the Skills collection only; other areas are not complete reviews.'} Up to 24 references follow your sort order. Node counts and connecting lines use the collection, search, date, citation and review filters, before concept or area selection. Position has no meaning; paper size uses a compressed citation scale.`;
 $('pair-scope').textContent=state.view==='concepts'?'Shared concept matches':'Shared topic assignments';
 const relevant=allPairs.filter(p=>state.view==='concepts'?(!state.concept||[p.a,p.b].includes(state.concept)):(!state.area||[p.a,p.b].includes(state.area)));
 const list=showAllPairs?relevant:relevant.slice(0,6);
 $('pairs').innerHTML=list.map(p=>`<button class="pair ${active(p.a)&&active(p.b)?'active':''}" data-pair-a="${p.a}" data-pair-b="${p.b}"><span>${esc(label(p.a))} ↔ ${esc(label(p.b))}</span><b>${p.ids.length}</b></button>`).join('')||'<p class="note">No shared references under these filters. Broaden the dates, search or citation settings.</p>';
 if(relevant.length>6)$('pairs').innerHTML+=`<button id="toggle-pairs">${showAllPairs?'Show fewer connections':`Show all ${relevant.length} connections`}</button>`;
}
function renderReferences(){
 const total=Math.max(1,Math.ceil(visibleRows.length/15));page=Math.min(page,total);const rows=visibleRows.slice((page-1)*15,page*15);
 $('references').innerHTML=rows.map(r=>`<article class="reference-row"><div><button class="reference-title" data-paper="${esc(r.id)}">${esc(r.title)}</button><p>${esc(r.citation)}</p><div class="tags">${matches(r).map(m=>`<span class="tag">${esc(label(m.id))}</span>`).join('')||'<span class="tag">No concept match</span>'}${M.isRetracted(r)?'<span class="tag warning">Retraction noted in catalog</span>':''}</div></div><div class="reference-numbers">${esc(r.year||'Year unknown')}<small>${citeLabel(r)}</small></div><div class="reference-status">${status(r)}<button data-paper="${esc(r.id)}">Inspect →</button></div></article>`).join('')||'<p class="empty">No references match. Try clearing a concept, date or citation filter.</p>';
 $('list-count').textContent=`${visibleRows.length} reference${visibleRows.length===1?'':'s'}`;$('page-count').textContent=`Page ${page} of ${total}`;$('previous').disabled=page<=1;$('next').disabled=page>=total;
}
function renderMatrix(){
 matrixRows=visibleRows.filter(r=>reviews[r.id]?.status==='checked');$('review-count').textContent=`${matrixRows.length} source checked`;
 $('matrix').innerHTML=`<table><thead><tr><th>Primary outcome</th>${Object.values(durations).map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${Object.entries(outcomes).map(([o,name])=>`<tr><th>${name}</th>${Object.entries(durations).map(([d,time])=>{const n=matrixRows.filter(r=>reviews[r.id].outcome===o&&reviews[r.id].duration===d).length;return `<td><button data-outcome="${o}" data-duration="${d}" aria-label="${n} source-checked references: ${name}, ${time}">${n}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table>`;$('cell-records').innerHTML='';
}
function render(){
 visibleRows=M.select(records,state,context());$('filter-error').textContent=state.from&&state.to&&Number(state.from)>Number(state.to)?'The start year is later than the end year. Adjust the range to see results.':'';
 const extra=['from','to','cites','unknown','area','area2','collection','review','sort'].filter(k=>state[k]!==M.defaults[k]).length;$('active-filter-count').textContent=extra?`· ${extra} active`:'';
 rules.forEach(c=>{const e=$('rule-count-'+c.id);if(e)e.textContent=`${records.filter(r=>matches(r).some(m=>m.id===c.id)).length} matching references`;});drawGraph();renderReferences();renderMatrix();
 const selectedFlag=$('selection-scope');if(selectedFlag)selectedFlag.textContent=visibleRows.some(r=>r.id===state.paper)?'In the current view':'Outside the current filters';
}
function formValue(form){return Object.fromEntries(new FormData(form));}
function renderInspector(){
 const r=byId.get(state.paper);if(!r)return;
 const v=drafts[r.id]||reviews[r.id]||{population:'',design:'',outcome:'unknown',duration:'unknown',quote:'',locator:'',note:'',status:'unreviewed'},ms=matches(r),ids=new Set(ms.map(m=>m.id));
 const related=records.filter(p=>p.id!==r.id).map(p=>({paper:p,shared:matches(p).filter(m=>ids.has(m.id))})).filter(p=>p.shared.length).sort((a,b)=>b.shared.length-a.shared.length||a.paper.id.localeCompare(b.paper.id)).slice(0,4);
 $('inspector').innerHTML=`<p class="eyebrow">REFERENCE DETAILS</p><h2>${esc(r.title)}</h2><p>${esc(r.citation)}</p><div class="metadata"><span class="pill">${citeLabel(r)}</span><span class="pill" id="selection-scope">${visibleRows.some(p=>p.id===r.id)?'In the current view':'Outside the current filters'}</span></div>${M.isRetracted(r)?'<p class="warning">The catalog notes a retraction. Check the source notice before using this reference.</p>':''}<a class="source-link" href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">Read original source ↗</a>${SKILLS_DATA.citations.records[r.id]?` <a class="source-link" href="${esc(safeURL(SKILLS_DATA.citations.records[r.id].work))}" target="_blank" rel="noopener noreferrer">Citation record ↗</a>`:''}<h3>Why it connects</h3>${ms.map(m=>`<div class="match"><h3>${esc(label(m.id))}</h3><p>${m.hits.map(h=>`“${esc(h.term)}” in ${esc(h.field)}`).join('<br>')}</p></div>`).join('')||'<p class="note">No phrase matches under the current rules.</p>'}<p class="note">GD assignments: ${r.topics.map(id=>esc(label(id))).join(' · ')}. Draft catalog and research-review assignments; check relevance in the source.</p>${r.topicReviews?.length?`<details><summary>Updated topic-review provenance</summary>${r.topicReviews.map(t=>`<p class="note">${esc(label(t.topic))} · ${esc(t.checkedOn)} · ${esc({'primary-fulltext':'AI-assisted full-text review','primary-summary':'Official summary inspected','primary-abstract':'Abstract inspected'}[t.access]||t.access)}<br>${esc(t.note)}<br>Record match: ${esc(t.identityMethod||'Canonical URL')}. <a href="${esc(safeURL(t.url))}" target="_blank" rel="noopener noreferrer">Reviewed source ↗</a><br><a href="topics/library.html?topic=${encodeURIComponent(t.topic)}">Open topic library →</a></p>`).join('')}</details>`:''}<details><summary>Related references</summary><p class="note">Across this Skills collection, ranked by shared concept matches; your current filters do not apply here.</p><div class="related-list">${related.map(({paper,shared})=>`<button data-paper="${esc(paper.id)}">${esc(paper.title)}<small>${shared.map(m=>esc(label(m.id))).join(' · ')}</small></button>`).join('')||'<p class="note">No shared concept matches.</p>'}</div></details><details class="review-details" ${drafts[r.id]?'open':''}><summary>Your source review · ${status(r).toLowerCase()}</summary><p class="note">Record what the source measures. A checked review requires an excerpt and locator; it is your assessment, not independent verification. Drafts save automatically but do not enter the matrix.</p><form class="review-form" id="review-form"><label>Population or sample<input name="population" maxlength="5000" value="${esc(v.population)}"></label><label>Study design<input name="design" maxlength="5000" value="${esc(v.design)}"></label><label>Primary measured outcome<select name="outcome">${options(outcomes,v.outcome)}</select></label><label>Follow-up for this outcome<select name="duration">${options(durations,v.duration)}</select></label><label>Source excerpt<textarea name="quote" maxlength="5000">${esc(v.quote)}</textarea></label><label>Page, section or source locator<input name="locator" maxlength="5000" value="${esc(v.locator)}"></label><label>Interpretation and limits<textarea name="note" maxlength="5000">${esc(v.note)}</textarea></label><label>Review status<select name="status">${options({unreviewed:'Draft / unreviewed',checked:'Source checked by me',excluded:'Exclude from this pilot'},v.status)}</select></label><button type="submit">Save assessment</button><p id="review-message" class="note" role="status">${drafts[r.id]?'Unsaved assessment restored from your draft.':''}</p></form></details>`;
 $('review-form').addEventListener('input',e=>{drafts[r.id]=formValue(e.currentTarget);persist();$('review-message').textContent='Draft saved in this browser. Save the assessment to update the matrix.';});
 $('review-form').onsubmit=e=>{e.preventDefault();try{reviews[r.id]=C.validateReview(formValue(e.target));delete drafts[r.id];persist();render();$('review-message').textContent='Assessment saved.';$('inspector').querySelector('.review-details > summary').textContent='Your source review · '+status(r).toLowerCase();}catch(err){$('review-message').textContent=err.message;}};
}
function refreshWorkspace(){cache.clear();renderRules();syncControls();$('gap-note').value=gapNote;persist();render();if(byId.has(state.paper))renderInspector();}
function noticeWithUndo(message,undo){$('message').textContent=message+' ';const b=document.createElement('button');b.textContent='Undo';b.onclick=()=>{undo();$('message').textContent='Previous workspace restored.';};$('message').append(b);}
document.addEventListener('click',e=>{const p=e.target.closest('[data-paper]');if(p){choosePaper(p.dataset.paper);return;}const pair=e.target.closest('[data-pair-a]');if(pair){choosePair(pair.dataset.pairA,pair.dataset.pairB);return;}const n=e.target.closest('[data-node]');if(n){change(state.view==='concepts'?{concept:state.concept===n.dataset.node?'':n.dataset.node,connection:''}:{area:state.area===n.dataset.node?'':n.dataset.node,area2:''});return;}const view=e.target.closest('[data-view]');if(view){change({view:view.dataset.view});return;}if(e.target.id==='toggle-pairs'){showAllPairs=!showAllPairs;drawGraph();return;}const cell=e.target.closest('[data-outcome]');if(cell){const rows=matrixRows.filter(r=>reviews[r.id].outcome===cell.dataset.outcome&&reviews[r.id].duration===cell.dataset.duration);$('cell-records').innerHTML=`<h3>${outcomes[cell.dataset.outcome]} · ${durations[cell.dataset.duration]}</h3>`+(rows.map(r=>`<button data-paper="${esc(r.id)}">${esc(r.title)}</button>`).join('')||'<p>No source-checked references in this cell of the current view. Further searching is needed.</p>');}});
$('graph').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.closest('[role=button]')){e.preventDefault();e.target.closest('[role=button]').dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
for(const k of Object.keys(M.defaults)){const input=$(k);if(input)input.addEventListener(['q','from','to','cites'].includes(k)?'input':'change',()=>change({[k]:input.value}));}
$('clear').onclick=()=>change({...M.defaults,view:state.view,size:state.size,paper:state.paper});$('reset-map').onclick=()=>change({concept:'',connection:'',area:'',area2:''});
$('previous').onclick=()=>{page--;renderReferences();document.querySelector('.references').scrollIntoView({block:'start'});};$('next').onclick=()=>{page++;renderReferences();document.querySelector('.references').scrollIntoView({block:'start'});};
$('rules-list').addEventListener('input',e=>{if(!e.target.dataset.rule)return;try{rules=C.validateRules(rules.map(c=>({...c,terms:c.id===e.target.dataset.rule?e.target.value.split('\n').map(t=>t.trim()).filter(Boolean):c.terms})));cache.clear();persist();page=1;render();if(state.paper)renderInspector();$('rule-message').textContent='Phrases applied. Reviews preserved.';}catch(err){$('rule-message').textContent=err.message;}});
$('reset-rules').onclick=()=>{const prior=JSON.parse(JSON.stringify(rules));rules=C.validateRules(C.defaults);refreshWorkspace();noticeWithUndo('Default phrases restored. Reviews preserved.',()=>{rules=prior;refreshWorkspace();});};
$('gap-note').value=gapNote;$('gap-note').oninput=e=>{gapNote=e.target.value;persist();};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(workspace(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='gd-skills-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('message').textContent='Workspace exported with rules, drafts, reviews and your research note.';};
$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('File too large (maximum 5 MB).');const incoming=validateWorkspace(JSON.parse(await file.text())),backup=JSON.stringify(workspace());try{localStorage.setItem(storageKey+'-before-import',localStorage.getItem(storageKey)||backup);}catch(_){throw Error('A backup could not be saved. Export your current work before importing in a browser with storage enabled.');}applyWorkspace(incoming);storageBlocked=false;refreshWorkspace();noticeWithUndo('Workspace imported.',()=>{applyWorkspace(validateWorkspace(JSON.parse(backup)));refreshWorkspace();});}catch(err){$('message').textContent='Import failed: '+err.message;}e.target.value='';};
$('share-view').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('message').textContent='View link copied. It shares filters and the selected paper; export a workspace to share edited rules or reviews.';}catch(_){$('message').textContent='Copy the URL from your address bar to share this view. Edited rules and reviews require a workspace export.';}};
window.addEventListener('popstate',()=>{state=M.readQuery(location.search);page=1;syncControls();render();if(state.paper)renderInspector();});
function updateThemeButton(){$('theme').textContent=document.documentElement.dataset.theme==='dark'?'Light mode':'Dark mode';}
$('theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{sessionStorage.setItem('gd-dashboard-visit-theme',theme);}catch(_){}updateThemeButton();};updateThemeButton();
$('snapshot').textContent=`${records.length} references · Catalog ${SKILLS_DATA.baseUpdated||SKILLS_DATA.updated} + topic review ${SKILLS_DATA.updated}`;
$('citation-method').textContent=`OpenAlex snapshot: ${SKILLS_DATA.citations.retrieved.slice(0,10)}. ${Object.keys(SKILLS_DATA.citations.records).length} of ${records.length} references have counts, matched by exact DOI (including arXiv DOI). Counts may combine versions and will change over time. The initial review queue contains up to 40 automatically selected studies with human-related catalog metadata and multiple concept matches; it is not representative.`;
renderRules();syncControls();if(['from','to','cites','area','area2'].some(k=>state[k]))$('more-filters').open=true;persist();render();if(state.paper){if(byId.has(state.paper))renderInspector();else $('message').textContent='The linked reference is not in this library snapshot.';}
